<template><Head title="Advisories"/><AuthenticatedLayout><template #header><div class="flex items-center justify-between"><div><h1 class="text-xl font-semibold">Relevant security advisories</h1><p class="mt-1 text-sm text-slate-500">CISA OT guidance matched against your actual inventory.</p></div><Link :href="route('advisories.create')" class="rounded-lg bg-teal-700 px-4 py-2 text-sm font-semibold text-white">Add advisory</Link></div></template><div class="mx-auto max-w-7xl px-4 py-8"><div class="mb-6 grid grid-cols-2 gap-3 sm:grid-cols-4"><div v-for="level in ['critical','high','medium','low']" :key="level" class="rounded-xl border bg-white p-4"><p class="text-xs font-semibold uppercase text-slate-500">Open {{level}}</p><p class="mt-2 text-2xl font-bold">{{openBySeverity[level]||0}}</p></div></div><div class="overflow-hidden rounded-xl border bg-white shadow-sm"><table class="min-w-full divide-y divide-slate-200"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-500"><tr><th class="px-5 py-3">Advisory</th><th class="px-5 py-3">Severity</th><th class="px-5 py-3">Affected assets</th><th class="px-5 py-3">Published</th></tr></thead><tbody class="divide-y text-sm"><tr v-for="item in advisories.data" :key="item.id"><td class="px-5 py-4"><Link :href="route('advisories.show',item.id)" class="font-semibold text-teal-800">{{item.title}}</Link><div class="text-slate-500">{{item.external_id}} · {{item.source.replace('_',' ')}}</div></td><td class="px-5 py-4 font-semibold uppercase">{{item.severity}}</td><td class="px-5 py-4">{{item.matches_count}}</td><td class="px-5 py-4 text-slate-500">{{item.published_at?new Date(item.published_at).toLocaleDateString():'Unknown'}}</td></tr><tr v-if="!advisories.data.length"><td colspan="4" class="px-5 py-12 text-center text-slate-500">No advisories ingested yet.</td></tr></tbody></table></div></div></AuthenticatedLayout></template>
